80: func VboxManageOutput(ctx context.Context, exe string, args ...string) (string, error) {
81: 	var stdout, stderr bytes.Buffer
82: 	logrus.Debugf("Executing VBoxManageOutput: %#v", args)
83: 	cmd := exec.CommandContext(ctx, exe, args...)
84: 	cmd.Stdout = &stdout
85: 	cmd.Stderr = &stderr
86: 	err := cmd.Run()
87: 
88: 	stderrString := strings.TrimSpace(stderr.String())
89: 
90: 	if _, ok := err.(*exec.ExitError); ok {
91: 		err = fmt.Errorf("VBoxManageOutput error: %s", stderrString)
92: 	}
93: 
94: 	return stdout.String(), err
95: }
