109: func FindSSHPort(ctx context.Context, vmName string) (port string, err error) {
110: 	info, err := VBoxManage(ctx, "showvminfo", vmName)
111: 	if err != nil {
112: 		return
113: 	}
114: 	portRe := regexp.MustCompile(`guestssh.*host port = (\d+)`)
115: 	sshPort := portRe.FindStringSubmatch(info)
116: 	if len(sshPort) >= 2 {
117: 		port = sshPort[1]
118: 	} else {
119: 		err = errors.New("failed to find guestssh port")
120: 	}
121: 	return
122: }
