42: 	// This script is indented to be run in docker or kubernetes containers only to ensure graceful shutdown of build,
43: 	// service and potentially other containers. It sends SIGTERM to all PIDs excluding itself and 1, in decreasing numeric
44: 	// order, positing that the higher PIDs are likely the processes blocking and thus preventing the container from
45: 	// shutting down cleanly. The inner while loop waits for up to 5 seconds for the last killed PID to exit before moving
46: 	// onto the next PID. Note that processes that are shells will ignore SIGTERM anyway, so this script is not as heavy
47: 	// handed as it might appear.
48: 	ContainerSigTermScriptForLinux = `PROCS=$(cd /proc && ls -rvd [0-9]*) &&
49: for P in $PROCS; do
50: 	if [ $$ -ne $P ] && [ $P -ne 1 ]; then
51: 		kill -TERM $P 2>/dev/null &&
52: 		ATTEMPTS=6 &&
53: 		while [ -e /proc/$P ] && [ $ATTEMPTS -gt 0 ]; do
54: 			sleep 1 && ATTEMPTS=$((ATTEMPTS-1));
55: 		done;
